import './App.css';
import { useEffect, useMemo, useState } from 'react';
import { request, download, API_URL } from './api/client';

function App() {
  const [authMode, setAuthMode] = useState('login');
  const [authForm, setAuthForm] = useState({
    email: '',
    password: '',
    firstName: '',
    lastName: '',
  });
  const [leadForm, setLeadForm] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    company: '',
    source: 'website',
    status: 'new',
    notes: '',
  });
  const [filters, setFilters] = useState({
    status: '',
    source: '',
    search: '',
    sort: 'desc',
  });
  const [page, setPage] = useState(1);
  const [leads, setLeads] = useState([]);
  const [meta, setMeta] = useState({ total: 0, pages: 1 });
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(() => localStorage.getItem('leadflow_token'));
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');

  const isAuthed = Boolean(token);

  const queryString = useMemo(() => {
    const params = new URLSearchParams();
    if (filters.status) params.set('status', filters.status);
    if (filters.source) params.set('source', filters.source);
    if (filters.search) params.set('search', filters.search);
    if (filters.sort) params.set('sort', filters.sort);
    params.set('page', page);
    params.set('limit', 10);
    return params.toString();
  }, [filters, page]);

  useEffect(() => {
    if (!isAuthed) return;

    const loadLeads = async () => {
      try {
        setLoading(true);
        const response = await request(`/api/leads?${queryString}`);
        setLeads(response.data || []);
        setMeta(response.meta || { total: 0, pages: 1 });
      } catch (error) {
        setMessage(error.message);
      } finally {
        setLoading(false);
      }
    };

    loadLeads();
  }, [isAuthed, queryString]);

  const handleAuthChange = (event) => {
    const { name, value } = event.target;
    setAuthForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleLeadChange = (event) => {
    const { name, value } = event.target;
    setLeadForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleFilterChange = (event) => {
    const { name, value } = event.target;
    setFilters((prev) => ({ ...prev, [name]: value }));
    setPage(1);
  };

  const submitAuth = async (event) => {
    event.preventDefault();
    setMessage('');

    try {
      setLoading(true);
      const path = authMode === 'login' ? '/api/auth/login' : '/api/auth/register';
      const payload = await request(path, {
        method: 'POST',
        body: authMode === 'login'
          ? { email: authForm.email, password: authForm.password }
          : authForm,
      });

      localStorage.setItem('leadflow_token', payload.token);
      setToken(payload.token);
      setUser(payload.user);
      setAuthForm({ email: '', password: '', firstName: '', lastName: '' });
      setMessage('');
    } catch (error) {
      setMessage(error.message);
    } finally {
      setLoading(false);
    }
  };

  const submitLead = async (event) => {
    event.preventDefault();
    setMessage('');

    try {
      setLoading(true);
      await request('/api/leads', { method: 'POST', body: leadForm });
      setLeadForm({
        firstName: '',
        lastName: '',
        email: '',
        phone: '',
        company: '',
        source: 'website',
        status: 'new',
        notes: '',
      });
      const response = await request(`/api/leads?${queryString}`);
      setLeads(response.data || []);
      setMeta(response.meta || { total: 0, pages: 1 });
    } catch (error) {
      setMessage(error.message);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (leadId) => {
    if (!window.confirm('Delete this lead?')) return;

    try {
      setLoading(true);
      await request(`/api/leads/${leadId}`, { method: 'DELETE' });
      const response = await request(`/api/leads?${queryString}`);
      setLeads(response.data || []);
      setMeta(response.meta || { total: 0, pages: 1 });
    } catch (error) {
      setMessage(error.message);
    } finally {
      setLoading(false);
    }
  };

  const handleExport = async () => {
    try {
      setLoading(true);
      const blob = await download(`/api/leads/export?${queryString}`);
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = 'leads.csv';
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      setMessage(error.message);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('leadflow_token');
    setToken(null);
    setUser(null);
    setLeads([]);
  };

  const canDelete = user?.role === 'admin';

  return (
    <div className="app">
      <header className="app-header">
        <div>
          <p className="eyebrow">Leadflow AI</p>
          <h1>Smart Leads Dashboard</h1>
          <p className="subtle">API: {API_URL}</p>
        </div>
        {isAuthed && (
          <div className="user-box">
            <div>
              <p className="user-name">{user?.firstName} {user?.lastName}</p>
              <p className="subtle">{user?.role}</p>
            </div>
            <button className="btn ghost" onClick={handleLogout}>Log out</button>
          </div>
        )}
      </header>

      {message && <div className="alert">{message}</div>}

      {!isAuthed ? (
        <section className="card auth">
          <div className="tab-row">
            <button
              className={`tab ${authMode === 'login' ? 'active' : ''}`}
              onClick={() => setAuthMode('login')}
            >
              Login
            </button>
            <button
              className={`tab ${authMode === 'register' ? 'active' : ''}`}
              onClick={() => setAuthMode('register')}
            >
              Register
            </button>
          </div>
          <form onSubmit={submitAuth} className="form-grid">
            {authMode === 'register' && (
              <>
                <input
                  name="firstName"
                  placeholder="First name"
                  value={authForm.firstName}
                  onChange={handleAuthChange}
                  required
                />
                <input
                  name="lastName"
                  placeholder="Last name"
                  value={authForm.lastName}
                  onChange={handleAuthChange}
                  required
                />
              </>
            )}
            <input
              type="email"
              name="email"
              placeholder="Email"
              value={authForm.email}
              onChange={handleAuthChange}
              required
            />
            <input
              type="password"
              name="password"
              placeholder="Password"
              value={authForm.password}
              onChange={handleAuthChange}
              required
            />
            <button className="btn" type="submit" disabled={loading}>
              {loading ? 'Please wait...' : authMode === 'login' ? 'Login' : 'Create account'}
            </button>
          </form>
        </section>
      ) : (
        <main className="dashboard">
          <section className="card">
            <h2>Create Lead</h2>
            <form onSubmit={submitLead} className="form-grid">
              <input name="firstName" placeholder="First name" value={leadForm.firstName} onChange={handleLeadChange} required />
              <input name="lastName" placeholder="Last name" value={leadForm.lastName} onChange={handleLeadChange} required />
              <input name="email" placeholder="Email" value={leadForm.email} onChange={handleLeadChange} required />
              <input name="phone" placeholder="Phone" value={leadForm.phone} onChange={handleLeadChange} />
              <input name="company" placeholder="Company" value={leadForm.company} onChange={handleLeadChange} />
              <select name="source" value={leadForm.source} onChange={handleLeadChange}>
                <option value="website">Website</option>
                <option value="referral">Referral</option>
                <option value="social">Social</option>
                <option value="cold_call">Cold call</option>
                <option value="event">Event</option>
              </select>
              <select name="status" value={leadForm.status} onChange={handleLeadChange}>
                <option value="new">New</option>
                <option value="contacted">Contacted</option>
                <option value="qualified">Qualified</option>
                <option value="converted">Converted</option>
                <option value="lost">Lost</option>
              </select>
              <textarea name="notes" placeholder="Notes" value={leadForm.notes} onChange={handleLeadChange} rows="3" />
              <button className="btn" type="submit" disabled={loading}>
                {loading ? 'Saving...' : 'Add lead'}
              </button>
            </form>
          </section>

          <section className="card">
            <div className="card-header">
              <div>
                <h2>Leads</h2>
                <p className="subtle">{meta.total} total leads</p>
              </div>
              <button className="btn ghost" onClick={handleExport}>Export CSV</button>
            </div>

            <div className="filters">
              <input
                name="search"
                placeholder="Search name or email"
                value={filters.search}
                onChange={handleFilterChange}
              />
              <select name="status" value={filters.status} onChange={handleFilterChange}>
                <option value="">All statuses</option>
                <option value="new">New</option>
                <option value="contacted">Contacted</option>
                <option value="qualified">Qualified</option>
                <option value="converted">Converted</option>
                <option value="lost">Lost</option>
              </select>
              <select name="source" value={filters.source} onChange={handleFilterChange}>
                <option value="">All sources</option>
                <option value="website">Website</option>
                <option value="referral">Referral</option>
                <option value="social">Social</option>
                <option value="cold_call">Cold call</option>
                <option value="event">Event</option>
              </select>
              <select name="sort" value={filters.sort} onChange={handleFilterChange}>
                <option value="desc">Newest first</option>
                <option value="asc">Oldest first</option>
              </select>
            </div>

            {loading ? (
              <p className="subtle">Loading...</p>
            ) : leads.length === 0 ? (
              <p className="subtle">No leads found.</p>
            ) : (
              <div className="table">
                <div className="table-row table-head">
                  <span>Name</span>
                  <span>Email</span>
                  <span>Company</span>
                  <span>Status</span>
                  <span>Source</span>
                  <span>Actions</span>
                </div>
                {leads.map((lead) => (
                  <div className="table-row" key={lead._id}>
                    <span>{lead.firstName} {lead.lastName}</span>
                    <span>{lead.email}</span>
                    <span>{lead.company || '-'}</span>
                    <span className={`pill ${lead.status}`}>{lead.status}</span>
                    <span>{lead.source}</span>
                    <span>
                      {canDelete ? (
                        <button className="btn tiny danger" onClick={() => handleDelete(lead._id)}>
                          Delete
                        </button>
                      ) : (
                        <span className="subtle">-</span>
                      )}
                    </span>
                  </div>
                ))}
              </div>
            )}

            <div className="pagination">
              <button
                className="btn ghost"
                onClick={() => setPage((prev) => Math.max(prev - 1, 1))}
                disabled={page === 1}
              >
                Prev
              </button>
              <span className="subtle">Page {page} of {meta.pages}</span>
              <button
                className="btn ghost"
                onClick={() => setPage((prev) => Math.min(prev + 1, meta.pages))}
                disabled={page >= meta.pages}
              >
                Next
              </button>
            </div>
          </section>
        </main>
      )}
    </div>
  );
}

export default App;
